{
  "name": "General Service Portal",
  "description": "A comprehensive portal for General Service management including Mess bookings, KRP (Vehicle) requests, and Maintenance tracking with interactive dashboards."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum ServiceType {
  MESS = 'Mess',
  KRP = 'KRP',
  MAINTENANCE = 'Maintenance'
}

export enum SubMenu {
  DASHBOARD = 'Dashboard',
  REQUEST = 'Request'
}

export enum RequestStatus {
  REQUESTED = 'Requested',
  ON_PROGRESS = 'On Progress',
  PENDING = 'Pending',
  CLOSE = 'Close'
}

export interface BaseRequest {
  id: string;
  type: ServiceType;
  status: RequestStatus;
  createdAt: string;
  function: string;
}

export interface MessRequest extends BaseRequest {
  location: 'Banjarbaru' | 'Batu Butok' | 'Long Ikis' | 'Tanjung';
  guestName: string;
  roomCount: number;
  requesterName: string;
  guestPhone: string;
  checkInDate: string;
  checkOutDate: string;
}

export interface KRPRequest extends BaseRequest {
  passengerName: string;
  passengerCount: number;
  passengerPhone: string;
  departureDate: string;
  departureTime: string;
  isRoundTrip: boolean;
  returnDate?: string;
  returnTime?: string;
}

export interface MaintenanceRequest extends BaseRequest {
  category: 'Fasilitas Umum' | 'Electrical maintenance' | 'Civil Maintenance' | 'AC Maintenance' | 'House Keeping';
  requesterName: string;
  requesterPhone: string;
  workDate: string;
  detail: string;
}

export type AnyRequest = MessRequest | KRPRequest | MaintenanceRequest;

import React, { useState, useEffect } from 'react';
import { 
  Building2, 
  Car, 
  Wrench, 
  LayoutDashboard, 
  FileText, 
  ChevronRight,
  Plus,
  Bell,
  User,
  Menu,
  X
} from 'lucide-react';
import { ServiceType, SubMenu, AnyRequest, RequestStatus } from './types';
import DashboardView from './components/DashboardView';
import MessRequestForm from './components/MessRequestForm';
import KRPRequestForm from './components/KRPRequestForm';
import MaintenanceRequestForm from './components/MaintenanceRequestForm';

const App: React.FC = () => {
  const [activeService, setActiveService] = useState<ServiceType>(ServiceType.MESS);
  const [activeSubMenu, setActiveSubMenu] = useState<SubMenu>(SubMenu.DASHBOARD);
  const [requests, setRequests] = useState<AnyRequest[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Load initial mock data
  useEffect(() => {
    const mockData: AnyRequest[] = [
      {
        id: '1',
        type: ServiceType.MESS,
        status: RequestStatus.REQUESTED,
        createdAt: new Date().toISOString(),
        location: 'Banjarbaru',
        guestName: 'Budi Santoso',
        roomCount: 1,
        requesterName: 'Admin GS',
        function: 'HRD',
        guestPhone: '08123456789',
        checkInDate: '2023-10-01',
        checkOutDate: '2023-10-03',
      },
      {
        id: '2',
        type: ServiceType.KRP,
        status: RequestStatus.ON_PROGRESS,
        createdAt: new Date().toISOString(),
        passengerName: 'Siti Aminah',
        passengerCount: 2,
        function: 'Finance',
        passengerPhone: '08112233445',
        departureDate: '2023-10-02',
        departureTime: '08:00',
        isRoundTrip: true,
        returnDate: '2023-10-02',
        returnTime: '17:00'
      }
    ];
    setRequests(mockData);
  }, []);

  const handleAddRequest = (newRequest: AnyRequest) => {
    setRequests(prev => [newRequest, ...prev]);
    setActiveSubMenu(SubMenu.DASHBOARD);
  };

  const handleUpdateStatus = (id: string, status: RequestStatus) => {
    setRequests(prev => prev.map(req => req.id === id ? { ...req, status } : req));
  };

  const currentServiceRequests = requests.filter(req => req.type === activeService);

  const getServiceIcon = (type: ServiceType) => {
    switch (type) {
      case ServiceType.MESS: return <Building2 size={20} />;
      case ServiceType.KRP: return <Car size={20} />;
      case ServiceType.MAINTENANCE: return <Wrench size={20} />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-50">
      {/* Sidebar Overlay for Mobile */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden" 
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-white border-r border-slate-200 transition-transform duration-300 transform
        lg:relative lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col">
          <div className="p-6 border-b border-slate-100 flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-lg flex items-center justify-center text-white">
              <Building2 size={24} />
            </div>
            <div>
              <h1 className="font-bold text-slate-900 tracking-tight">GS Portal</h1>
              <p className="text-xs text-slate-500">General Service System</p>
            </div>
          </div>

          <nav className="flex-1 p-4 space-y-8 overflow-y-auto">
            {/* Main Menu Sections */}
            <div>
              <p className="px-3 mb-2 text-xs font-semibold text-slate-400 uppercase tracking-wider">Layanan Utama</p>
              <div className="space-y-1">
                {[ServiceType.MESS, ServiceType.KRP, ServiceType.MAINTENANCE].map((service) => (
                  <button
                    key={service}
                    onClick={() => {
                      setActiveService(service);
                      setIsSidebarOpen(false);
                    }}
                    className={`w-full flex items-center justify-between px-3 py-2 rounded-lg text-sm font-medium transition-colors ${
                      activeService === service 
                      ? 'bg-indigo-50 text-indigo-700' 
                      : 'text-slate-600 hover:bg-slate-50 hover:text-slate-900'
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      {getServiceIcon(service)}
                      {service}
                    </div>
                    {activeService === service && <ChevronRight size={16} />}
                  </button>
                ))}
              </div>
            </div>

            {/* Sub Menu */}
            <div>
              <p className="px-3 mb-2 text-xs font-semibold text-slate-400 uppercase tracking-wider">Menu {activeService}</p>
              <div className="space-y-1">
                {[SubMenu.DASHBOARD, SubMenu.REQUEST].map((sub) => (
                  <button
                    key={sub}
                    onClick={() => {
                      setActiveSubMenu(sub);
                      setIsSidebarOpen(false);
                    }}
                    className={`w-full flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-colors ${
                      activeSubMenu === sub 
                      ? 'bg-indigo-600 text-white shadow-md' 
                      : 'text-slate-600 hover:bg-slate-50 hover:text-slate-900'
                    }`}
                  >
                    {sub === SubMenu.DASHBOARD ? <LayoutDashboard size={20} /> : <FileText size={20} />}
                    {sub}
                  </button>
                ))}
              </div>
            </div>
          </nav>

          <div className="p-4 border-t border-slate-100">
            <div className="flex items-center gap-3 p-2 bg-slate-50 rounded-xl">
              <div className="w-8 h-8 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-700">
                <User size={16} />
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-slate-900 truncate">General User</p>
                <p className="text-xs text-slate-500 truncate">Operations</p>
              </div>
            </div>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        {/* Header */}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-4 lg:px-8">
          <div className="flex items-center gap-4">
            <button 
              className="lg:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-lg"
              onClick={() => setIsSidebarOpen(true)}
            >
              <Menu size={20} />
            </button>
            <h2 className="text-lg font-semibold text-slate-900 flex items-center gap-2">
              <span className="text-slate-400 font-normal">{activeService}</span>
              <span className="text-slate-300">/</span>
              <span>{activeSubMenu}</span>
            </h2>
          </div>
          <div className="flex items-center gap-3">
            <button className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all relative">
              <Bell size={20} />
              <span className="absolute top-1.5 right-1.5 w-2 h-2 bg-red-500 rounded-full border-2 border-white"></span>
            </button>
            <div className="h-8 w-px bg-slate-200 mx-1"></div>
            <button 
              onClick={() => setActiveSubMenu(SubMenu.REQUEST)}
              className="hidden sm:flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition-all shadow-sm"
            >
              <Plus size={18} />
              Buat Request Baru
            </button>
          </div>
        </header>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-4 lg:p-8">
          {activeSubMenu === SubMenu.DASHBOARD ? (
            <DashboardView 
              requests={currentServiceRequests} 
              onUpdateStatus={handleUpdateStatus} 
            />
          ) : (
            <div className="max-w-4xl mx-auto">
              <div className="mb-6">
                <h3 className="text-xl font-bold text-slate-900">Formulir Pengajuan {activeService}</h3>
                <p className="text-sm text-slate-500">Lengkapi data di bawah ini untuk memproses permintaan Anda.</p>
              </div>

              {activeService === ServiceType.MESS && <MessRequestForm onSubmit={handleAddRequest} />}
              {activeService === ServiceType.KRP && <KRPRequestForm onSubmit={handleAddRequest} />}
              {activeService === ServiceType.MAINTENANCE && <MaintenanceRequestForm onSubmit={handleAddRequest} />}
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { 
  Inbox, 
  RefreshCw, 
  Clock, 
  CheckCircle2, 
  Filter, 
  Calendar,
  User,
  MapPin,
  Tag,
  Phone,
  Briefcase
} from 'lucide-react';
import { AnyRequest, RequestStatus, ServiceType, MessRequest, KRPRequest, MaintenanceRequest } from '../types';

interface DashboardViewProps {
  requests: AnyRequest[];
  onUpdateStatus: (id: string, status: RequestStatus) => void;
}

const DashboardView: React.FC<DashboardViewProps> = ({ requests, onUpdateStatus }) => {
  const [selectedStatus, setSelectedStatus] = useState<RequestStatus | null>(null);

  const getStatusCount = (status: RequestStatus) => {
    return requests.filter(req => req.status === status).length;
  };

  const filteredRequests = selectedStatus 
    ? requests.filter(req => req.status === selectedStatus)
    : requests;

  const StatusCard = ({ status, icon: Icon, colorClass, borderClass }: { status: RequestStatus, icon: any, colorClass: string, borderClass: string }) => {
    const isActive = selectedStatus === status;
    return (
      <button 
        onClick={() => setSelectedStatus(isActive ? null : status)}
        className={`flex-1 p-5 rounded-2xl border bg-white transition-all text-left shadow-sm hover:shadow-md ${isActive ? borderClass + ' ring-2 ring-opacity-20 ' + borderClass : 'border-slate-100 hover:border-slate-200'}`}
      >
        <div className="flex justify-between items-start mb-4">
          <div className={`p-2.5 rounded-xl ${colorClass}`}>
            <Icon size={24} />
          </div>
          <span className="text-2xl font-bold text-slate-900">{getStatusCount(status)}</span>
        </div>
        <div>
          <h4 className="font-semibold text-slate-900">{status}</h4>
          <p className="text-xs text-slate-500 mt-1">Total pengajuan aktif</p>
        </div>
      </button>
    );
  };

  const renderRequestDetails = (req: AnyRequest) => {
    switch (req.type) {
      case ServiceType.MESS:
        const mess = req as MessRequest;
        return (
          <div className="grid grid-cols-2 gap-y-2 text-sm">
            <div className="flex items-center gap-2 text-slate-500"><MapPin size={14} /> Lokasi:</div>
            <div className="font-medium text-slate-900">{mess.location}</div>
            <div className="flex items-center gap-2 text-slate-500"><User size={14} /> Tamu:</div>
            <div className="font-medium text-slate-900">{mess.guestName}</div>
            <div className="flex items-center gap-2 text-slate-500"><Calendar size={14} /> Durasi:</div>
            <div className="font-medium text-slate-900 text-xs">{mess.checkInDate} - {mess.checkOutDate}</div>
          </div>
        );
      case ServiceType.KRP:
        const krp = req as KRPRequest;
        return (
          <div className="grid grid-cols-2 gap-y-2 text-sm">
            <div className="flex items-center gap-2 text-slate-500"><User size={14} /> Penumpang:</div>
            <div className="font-medium text-slate-900">{krp.passengerName} ({krp.passengerCount})</div>
            <div className="flex items-center gap-2 text-slate-500"><Calendar size={14} /> Berangkat:</div>
            <div className="font-medium text-slate-900 text-xs">{krp.departureDate} @ {krp.departureTime}</div>
            {krp.isRoundTrip && (
              <>
                <div className="flex items-center gap-2 text-slate-500 text-xs italic">Pulang Pergi</div>
                <div className="font-medium text-slate-900 text-xs italic">{krp.returnDate} @ {krp.returnTime}</div>
              </>
            )}
          </div>
        );
      case ServiceType.MAINTENANCE:
        const main = req as MaintenanceRequest;
        return (
          <div className="grid grid-cols-2 gap-y-2 text-sm">
            <div className="flex items-center gap-2 text-slate-500"><Tag size={14} /> Kategori:</div>
            <div className="font-medium text-slate-900">{main.category}</div>
            <div className="flex items-center gap-2 text-slate-500"><Clock size={14} /> Detail:</div>
            <div className="font-medium text-slate-900 truncate" title={main.detail}>{main.detail}</div>
          </div>
        );
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Summary Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatusCard 
          status={RequestStatus.REQUESTED} 
          icon={Inbox} 
          colorClass="bg-blue-100 text-blue-600" 
          borderClass="border-blue-500" 
        />
        <StatusCard 
          status={RequestStatus.ON_PROGRESS} 
          icon={RefreshCw} 
          colorClass="bg-amber-100 text-amber-600" 
          borderClass="border-amber-500" 
        />
        <StatusCard 
          status={RequestStatus.PENDING} 
          icon={Clock} 
          colorClass="bg-rose-100 text-rose-600" 
          borderClass="border-rose-500" 
        />
        <StatusCard 
          status={RequestStatus.CLOSE} 
          icon={CheckCircle2} 
          colorClass="bg-emerald-100 text-emerald-600" 
          borderClass="border-emerald-500" 
        />
      </div>

      {/* List Header */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h3 className="text-lg font-bold text-slate-900">Detail Pekerjaan</h3>
          <p className="text-sm text-slate-500">
            {selectedStatus ? `Menampilkan pengajuan dengan status "${selectedStatus}"` : 'Menampilkan semua pengajuan pekerjaan'}
          </p>
        </div>
        <div className="flex items-center gap-2 bg-white p-1 rounded-lg border border-slate-200 shadow-sm">
          <button 
            onClick={() => setSelectedStatus(null)}
            className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${!selectedStatus ? 'bg-indigo-600 text-white' : 'text-slate-600 hover:bg-slate-50'}`}
          >
            Semua
          </button>
          <div className="w-px h-4 bg-slate-200 mx-1"></div>
          <Filter size={14} className="text-slate-400 mx-2" />
        </div>
      </div>

      {/* Job Grid */}
      {filteredRequests.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
          {filteredRequests.map((req) => (
            <div key={req.id} className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm hover:shadow-md transition-all group">
              <div className="p-5 border-b border-slate-50">
                <div className="flex justify-between items-start mb-4">
                  <div className="flex items-center gap-2">
                    <span className="text-xs font-bold text-slate-400">#{req.id.slice(0, 5)}</span>
                    <span className={`px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider rounded-full ${
                      req.status === RequestStatus.REQUESTED ? 'bg-blue-50 text-blue-600' :
                      req.status === RequestStatus.ON_PROGRESS ? 'bg-amber-50 text-amber-600' :
                      req.status === RequestStatus.PENDING ? 'bg-rose-50 text-rose-600' :
                      'bg-emerald-50 text-emerald-600'
                    }`}>
                      {req.status}
                    </span>
                  </div>
                  <div className="text-[10px] text-slate-400 font-medium">
                    {new Date(req.createdAt).toLocaleDateString()}
                  </div>
                </div>

                <h4 className="font-bold text-slate-900 mb-4 group-hover:text-indigo-600 transition-colors">
                  {req.type === ServiceType.MAINTENANCE ? (req as MaintenanceRequest).category : (req as any).requesterName}
                </h4>

                <div className="bg-slate-50 p-4 rounded-xl border border-slate-100">
                  {renderRequestDetails(req)}
                </div>
              </div>

              <div className="p-4 bg-white flex items-center justify-between">
                <div className="flex flex-col">
                  <span className="text-[10px] text-slate-400 uppercase font-bold tracking-widest">Fungsi</span>
                  <span className="text-sm font-semibold text-slate-700">{req.function}</span>
                </div>
                <div className="flex gap-1">
                  <select 
                    value={req.status}
                    onChange={(e) => onUpdateStatus(req.id, e.target.value as RequestStatus)}
                    className="text-xs font-semibold bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all cursor-pointer"
                  >
                    {Object.values(RequestStatus).map(s => (
                      <option key={s} value={s}>{s}</option>
                    ))}
                  </select>
                </div>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className="flex flex-col items-center justify-center py-20 bg-white rounded-3xl border-2 border-dashed border-slate-200">
          <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center text-slate-400 mb-4">
            <Inbox size={32} />
          </div>
          <h4 className="text-lg font-semibold text-slate-900">Tidak Ada Pengajuan</h4>
          <p className="text-sm text-slate-500">Belum ada data pengajuan untuk filter ini.</p>
        </div>
      )}
    </div>
  );
};

export default DashboardView;

import React, { useState } from 'react';
import { ServiceType, RequestStatus, MessRequest } from '../types';
import { Building2, Save } from 'lucide-react';

interface Props {
  onSubmit: (req: MessRequest) => void;
}

const MessRequestForm: React.FC<Props> = ({ onSubmit }) => {
  const [formData, setFormData] = useState({
    location: 'Banjarbaru' as const,
    guestName: '',
    roomCount: 1,
    requesterName: '',
    function: '',
    guestPhone: '',
    checkInDate: '',
    checkOutDate: ''
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newRequest: MessRequest = {
      ...formData,
      id: Math.random().toString(36).substring(2, 9),
      type: ServiceType.MESS,
      status: RequestStatus.REQUESTED,
      createdAt: new Date().toISOString(),
    };
    onSubmit(newRequest);
  };

  return (
    <form onSubmit={handleSubmit} className="bg-white rounded-2xl border border-slate-200 p-6 lg:p-8 shadow-sm space-y-6 animate-in slide-in-from-bottom-4 duration-500">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="space-y-2">
          <label className="text-sm font-semibold text-slate-700">Pilih Mess</label>
          <div className="grid grid-cols-2 gap-2">
            {['Banjarbaru', 'Batu Butok', 'Long Ikis', 'Tanjung'].map(loc => (
              <button
                key={loc}
                type="button"
                onClick={() => setFormData(prev => ({ ...prev, location: loc as any }))}
                className={`px-4 py-3 rounded-xl border text-sm font-medium transition-all ${
                  formData.location === loc 
                  ? 'bg-indigo-50 border-indigo-600 text-indigo-700 ring-1 ring-indigo-600' 
                  : 'bg-white border-slate-200 text-slate-600 hover:border-slate-300'
                }`}
              >
                {loc}
              </button>
            ))}
          </div>
        </div>

        <div className="space-y-2">
          <label className="text-sm font-semibold text-slate-700">Nama Tamu</label>
          <input
            required
            type="text"
            className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all placeholder:text-slate-400"
            placeholder="Contoh: Budi Santoso"
            value={formData.guestName}
            onChange={e => setFormData(prev => ({ ...prev, guestName: e.target.value }))}
          />
        </div>

        <div className="space-y-2">
          <label className="text-sm font-semibold text-slate-700">Jumlah Kamar</label>
          <input
            required
            type="number"
            min="1"
            className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all"
            value={formData.roomCount}
            onChange={e => setFormData(prev => ({ ...prev, roomCount: parseInt(e.target.value) }))}
          />
        </div>

        <div className="space-y-2">
          <label className="text-sm font-semibold text-slate-700">Nomor Handphone Tamu</label>
          <input
            required
            type="tel"
            className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all placeholder:text-slate-400"
            placeholder="08xxxxxxxxxx"
            value={formData.guestPhone}
            onChange={e => setFormData(prev => ({ ...prev, guestPhone: e.target.value }))}
          />
        </div>

        <div className="space-y-2">
          <label className="text-sm font-semibold text-slate-700">Nama Pemesan</label>
          <input
            required
            type="text"
            className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all"
            value={formData.requesterName}
            onChange={e => setFormData(prev => ({ ...prev, requesterName: e.target.value }))}
          />
        </div>

        <div className="space-y-2">
          <label className="text-sm font-semibold text-slate-700">Fungsi / Departemen</label>
          <input
            required
            type="text"
            className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all"
            value={formData.function}
            onChange={e => setFormData(prev => ({ ...prev, function: e.target.value }))}
          />
        </div>

        <div className="space-y-2">
