                  <p className="text-slate-500 dark:text-slate-400 mt-1">Silakan lengkapi informasi pengajuan di bawah ini.</p>
                </div>

                {activeService === ServiceType.MESS && <MessRequestForm onSubmit={handleAddRequest} />}
                {activeService === ServiceType.KRP && <KRPRequestForm onSubmit={handleAddRequest} />}
                {activeService === ServiceType.MAINTENANCE && <MaintenanceRequestForm onSubmit={handleAddRequest} />}
              </div>
            )}
          </div>
        </div>
      </main>

      {/* Bottom Navigation - Mobile Only */}
      <nav className="lg:hidden fixed bottom-0 inset-x-0 h-16 bg-white dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800 flex items-center justify-around z-40 transition-colors">
        {[ServiceType.MESS, ServiceType.KRP, ServiceType.MAINTENANCE].map((service) => (
          <button
            key={service}
            onClick={() => setActiveService(service)}
            className={`flex flex-col items-center gap-1 transition-all px-4 ${
              activeService === service ? 'text-indigo-600 dark:text-indigo-400 scale-110' : 'text-slate-400 dark:text-slate-500'
            }`}
          >
            {getServiceIcon(service)}
            <span className="text-[10px] font-bold uppercase tracking-wide">{service}</span>
          </button>
        ))}
        <button 
          onClick={() => setActiveSubMenu(SubMenu.REQUEST)}
          className={`flex flex-col items-center gap-1 transition-all px-4 ${
            activeSubMenu === SubMenu.REQUEST ? 'text-indigo-600 dark:text-indigo-400 scale-110' : 'text-slate-400 dark:text-slate-500'
          }`}
        >
          <Plus size={20} />
          <span className="text-[10px] font-bold uppercase tracking-wide">New</span>
        </button>
      </nav>
    </div>
  );
};

