        onClick={() => setSelectedStatus(isActive ? null : status)}
        className={`relative flex-1 p-6 rounded-[2rem] bg-white dark:bg-slate-900 border transition-all text-left group overflow-hidden ${
          isActive 
          ? `ring-4 ring-offset-4 dark:ring-offset-slate-950 border-transparent shadow-2xl ${activeClass}` 
          : 'border-slate-100 dark:border-slate-800 hover:border-indigo-200 dark:hover:border-indigo-900 shadow-sm'
        }`}
      >
        <div className="relative z-10 flex justify-between items-start mb-6">
          <div className={`p-3 rounded-2xl ${isActive ? 'bg-white/20 text-white' : colorClass}`}>
            <Icon size={24} />
          </div>
          <span className={`text-3xl font-black ${isActive ? 'text-white' : 'text-slate-900 dark:text-white'}`}>
            {getStatusCount(status)}
          </span>
        </div>
        <div className="relative z-10">
          <h4 className={`font-bold tracking-tight text-lg ${isActive ? 'text-white' : 'text-slate-900 dark:text-white'}`}>
            {status}
