          <p className={`text-xs mt-1 ${isActive ? 'text-white/70' : 'text-slate-500 dark:text-slate-400'}`}>
            {status === RequestStatus.CLOSE ? 'Pekerjaan Selesai' : 'Pengajuan Berjalan'}
          </p>
        </div>
        {/* Abstract background shape for active card */}
        {isActive && (
          <div className="absolute -right-4 -bottom-4 w-24 h-24 bg-white/10 rounded-full blur-2xl"></div>
        )}
