              </div>
            </div>
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 rounded-full bg-amber-50 dark:bg-amber-900/30 flex items-center justify-center text-amber-600 dark:text-amber-400 flex-shrink-0">
                <User size={14} />
              </div>
              <div>
                <p className="text-[10px] text-slate-400 dark:text-slate-500 font-bold uppercase">Tamu</p>
                <p className="font-semibold text-slate-900 dark:text-slate-100">{mess.guestName}</p>
              </div>
            </div>
            <div className="flex items-center gap-3">
