  Sun,
  Moon
} from 'lucide-react';
import { ServiceType, SubMenu, AnyRequest, RequestStatus } from './types';
import DashboardView from './components/DashboardView';
import MessRequestForm from './components/MessRequestForm';
import KRPRequestForm from './components/KRPRequestForm';
import MaintenanceRequestForm from './components/MaintenanceRequestForm';

const App: React.FC = () => {
  const [activeService, setActiveService] = useState<ServiceType>(ServiceType.MESS);
  const [activeSubMenu, setActiveSubMenu] = useState<SubMenu>(SubMenu.DASHBOARD);
  const [requests, setRequests] = useState<AnyRequest[]>([]);
  const [isDarkMode, setIsDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem('theme') === 'dark' || 
        (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
    }
    return false;
  });

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  useEffect(() => {
    const mockData: AnyRequest[] = [
      {
        id: '1',
        type: ServiceType.MESS,
        status: RequestStatus.REQUESTED,
        createdAt: new Date().toISOString(),
        location: 'Banjarbaru',
        guestName: 'Budi Santoso',
        roomCount: 1,
        requesterName: 'Admin GS',
        function: 'HRD',
        guestPhone: '08123456789',
        checkInDate: '2023-10-01',
        checkOutDate: '2023-10-03',
      },
      {
        id: '2',
        type: ServiceType.KRP,
        status: RequestStatus.ON_PROGRESS,
        createdAt: new Date().toISOString(),
        passengerName: 'Siti Aminah',
        passengerCount: 2,
        function: 'Finance',
        passengerPhone: '08112233445',
        departureDate: '2023-10-02',
        departureTime: '08:00',
        isRoundTrip: true,
        returnDate: '2023-10-02',
        returnTime: '17:00'
      }
    ];
    setRequests(mockData);
  }, []);

  const handleAddRequest = (newRequest: AnyRequest) => {
    setRequests(prev => [newRequest, ...prev]);
    setActiveSubMenu(SubMenu.DASHBOARD);
  };

  const handleUpdateStatus = (id: string, status: RequestStatus) => {
    setRequests(prev => prev.map(req => req.id === id ? { ...req, status } : req));
  };

  const currentServiceRequests = requests.filter(req => req.type === activeService);

  const getServiceIcon = (type: ServiceType, size = 20) => {
    switch (type) {
      case ServiceType.MESS: return <Building2 size={size} />;
      case ServiceType.KRP: return <Car size={size} />;
      case ServiceType.MAINTENANCE: return <Wrench size={size} />;
    }
  };

  const getDisplayName = (type: ServiceType) => {
    return type === ServiceType.MAINTENANCE ? 'Maint.' : type;
  };

  return (
    <div className="flex flex-col lg:flex-row min-h-screen bg-slate-50 dark:bg-slate-950 transition-colors duration-300 font-sans scrollbar-hide">

      {/* Desktop Sidebar */}
      <aside className="hidden lg:flex flex-col w-64 bg-white dark:bg-slate-900 border-r border-slate-200 dark:border-slate-800 sticky top-0 h-screen transition-colors scrollbar-hide">
        <div className="p-6 border-b border-slate-100 dark:border-slate-800">
          <h1 className="font-black text-slate-900 dark:text-white text-xl tracking-tight">General Service</h1>
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Management Portal</p>
        </div>

        <nav className="flex-1 p-4 space-y-2 overflow-y-auto scrollbar-hide">
          {[ServiceType.MESS, ServiceType.KRP, ServiceType.MAINTENANCE].map((service) => (
            <button
              key={service}
              onClick={() => {
                setActiveService(service);
                setActiveSubMenu(SubMenu.DASHBOARD);
              }}
              className={`w-full flex items-center justify-between px-4 py-3 rounded-xl text-sm font-bold transition-all ${
                activeService === service 
                ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200 dark:shadow-none' 
                : 'text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800 hover:text-slate-900 dark:hover:text-white'
              }`}
            >
              <div className="flex items-center gap-3">
                {getServiceIcon(service)}
                {getDisplayName(service)}
              </div>
              {activeService === service && <ChevronRight size={14} />}
            </button>
          ))}
        </nav>

        <div className="p-4 border-t border-slate-100 dark:border-slate-800">
          <button 
            onClick={() => setIsDarkMode(!isDarkMode)}
            className="w-full flex items-center justify-center gap-2 py-3 rounded-xl text-[11px] font-bold text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition-all border border-slate-200 dark:border-slate-800 uppercase tracking-wider"
          >
            {isDarkMode ? <Sun size={14} /> : <Moon size={14} />}
            {isDarkMode ? 'LIGHT MODE' : 'DARK MODE'}
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col min-w-0 pb-20 lg:pb-0 scrollbar-hide">

        {/* Fixed Top Header */}
        <div className="sticky top-0 z-40">
            <header className="h-16 lg:h-18 flex items-center justify-between px-6 lg:px-10 bg-white/95 dark:bg-slate-900/95 backdrop-blur-sm border-b border-slate-200 dark:border-slate-800 transition-colors">
                <div className="flex items-center gap-2 text-slate-900 dark:text-white">
                    <div className="lg:hidden w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white mr-1">
                    {getServiceIcon(activeService, 16)}
                    </div>
                    <h2 className="text-md lg:text-lg font-black tracking-tight">{getDisplayName(activeService)}</h2>
                    <span className="text-slate-300 dark:text-slate-700 mx-2">/</span>
                    <span className="text-slate-400 dark:text-slate-500 text-xs font-bold uppercase tracking-wider">{activeSubMenu}</span>
                </div>

                <div className="lg:hidden flex items-center gap-2">
                    <button 
                    onClick={() => setIsDarkMode(!isDarkMode)}
                    className="p-2 text-slate-400 dark:text-slate-500"
                    >
                    {isDarkMode ? <Sun size={20} /> : <Moon size={20} />}
                    </button>
                </div>
            </header>

            {/* Dashboard / Request Tab Switcher - Fixed under Header */}
            <div className="bg-slate-50/90 dark:bg-slate-950/90 backdrop-blur-md px-4 lg:px-10 py-3 lg:py-4 border-b border-slate-200 dark:border-slate-800">
                <div className="max-w-4xl mx-auto flex justify-center lg:justify-start">
                    <div className="flex p-1 bg-slate-200 dark:bg-slate-800 rounded-[1rem] transition-colors w-full sm:w-80">
                    {[SubMenu.DASHBOARD, SubMenu.REQUEST].map((sub) => (
                        <button
                        key={sub}
                        onClick={() => setActiveSubMenu(sub)}
                        className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-[0.75rem] text-[10px] font-black transition-all ${
                            activeSubMenu === sub 
                            ? 'bg-white dark:bg-slate-700 text-indigo-600 dark:text-white shadow-sm' 
                            : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-300'
                        }`}
                        >
                        {sub === SubMenu.DASHBOARD ? <LayoutDashboard size={12} /> : <FileText size={12} />}
                        {sub.toUpperCase()}
                        </button>
                    ))}
                    </div>
                </div>
            </div>
        </div>

        {/* Dynamic Content */}
        <div className="flex-1 overflow-y-auto p-4 lg:p-10 scrollbar-hide">
          <div className="max-w-7xl mx-auto">
            {activeSubMenu === SubMenu.DASHBOARD ? (
              <DashboardView 
                requests={currentServiceRequests} 
                onUpdateStatus={handleUpdateStatus} 
              />
            ) : (
              <div className="max-w-4xl mx-auto animate-in fade-in slide-in-from-bottom-2 duration-300">
                {activeService === ServiceType.MESS && <MessRequestForm onSubmit={handleAddRequest} />}
                {activeService === ServiceType.KRP && <KRPRequestForm onSubmit={handleAddRequest} />}
                {activeService === ServiceType.MAINTENANCE && <MaintenanceRequestForm onSubmit={handleAddRequest} />}
              </div>
            )}
          </div>
        </div>
      </main>

      {/* Simplified Mobile Bottom Navigation - Distribute Evenly */}
      <nav className="lg:hidden fixed bottom-0 inset-x-0 h-16 bg-white/95 dark:bg-slate-900/95 backdrop-blur-sm border-t border-slate-200 dark:border-slate-800 grid grid-cols-3 z-40 transition-colors">
        {[ServiceType.MESS, ServiceType.KRP, ServiceType.MAINTENANCE].map((service) => (
          <button
            key={service}
            onClick={() => {
              setActiveService(service);
              setActiveSubMenu(SubMenu.DASHBOARD);
            }}
            className={`flex flex-col items-center justify-center gap-1 transition-all h-full ${
              activeService === service ? 'text-indigo-600 dark:text-indigo-400' : 'text-slate-400 dark:text-slate-500'
            }`}
          >
            <div className={`p-1.5 rounded-xl transition-all ${activeService === service ? 'bg-indigo-50 dark:bg-indigo-900/20' : ''}`}>
              {getServiceIcon(service, 20)}
            </div>
            <span className="text-[9px] font-black uppercase tracking-widest leading-none">{getDisplayName(service)}</span>
          </button>
        ))}
      </nav>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { 
  Inbox, 
  RefreshCw, 
  Clock, 
  CheckCircle2, 
  Filter, 
  Calendar,
  User,
  MapPin,
  Tag
} from 'lucide-react';
import { AnyRequest, RequestStatus, ServiceType, MessRequest, KRPRequest, MaintenanceRequest } from '../types';

interface DashboardViewProps {
  requests: AnyRequest[];
  onUpdateStatus: (id: string, status: RequestStatus) => void;
}

const DashboardView: React.FC<DashboardViewProps> = ({ requests, onUpdateStatus }) => {
  const [selectedStatus, setSelectedStatus] = useState<RequestStatus | null>(null);

  const getStatusCount = (status: RequestStatus) => {
    return requests.filter(req => req.status === status).length;
  };

  const filteredRequests = selectedStatus 
    ? requests.filter(req => req.status === selectedStatus)
    : requests;

  const StatusCard = ({ status, icon: Icon, colorClass, activeClass }: { status: RequestStatus, icon: any, colorClass: string, activeClass: string }) => {
    const isActive = selectedStatus === status;
    return (
      <button 
        onClick={() => setSelectedStatus(isActive ? null : status)}
        className={`flex-1 p-4 lg:p-5 rounded-[1.25rem] bg-white dark:bg-slate-900 border transition-all text-left group overflow-hidden ${
          isActive 
          ? `ring-2 ring-indigo-500/50 border-transparent shadow-lg ${activeClass}` 
          : 'border-slate-200 dark:border-slate-800 hover:border-indigo-200 dark:hover:border-indigo-900 shadow-sm'
        }`}
      >
        <div className="flex justify-between items-start mb-3">
          <div className={`p-1.5 rounded-lg ${isActive ? 'bg-white/20 text-white' : colorClass}`}>
            <Icon size={18} />
          </div>
          <span className={`text-xl lg:text-2xl font-black ${isActive ? 'text-white' : 'text-slate-900 dark:text-white'}`}>
            {getStatusCount(status)}
          </span>
        </div>
        <div>
          <h4 className={`font-bold tracking-tight text-[11px] lg:text-xs uppercase ${isActive ? 'text-white' : 'text-slate-900 dark:text-white'}`}>
            {status}
          </h4>
        </div>
      </button>
    );
  };

  const renderRequestDetails = (req: AnyRequest) => {
    const detailLabelClass = "text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest";
    const detailValueClass = "text-xs font-semibold text-slate-700 dark:text-slate-300";

    switch (req.type) {
      case ServiceType.MESS:
        const mess = req as MessRequest;
        return (
          <div className="space-y-3">
            <div className="grid grid-cols-2 gap-2">
                <div>
                    <p className={detailLabelClass}>Lokasi</p>
                    <p className={detailValueClass}>{mess.location}</p>
                </div>
                <div>
                    <p className={detailLabelClass}>Tamu</p>
                    <p className={detailValueClass}>{mess.guestName}</p>
                </div>
            </div>
            <div className="flex items-center gap-2 pt-2 border-t border-slate-50 dark:border-slate-800/50">
               <Calendar size={12} className="text-slate-400" />
               <span className="text-[10px] font-medium text-slate-500">{mess.checkInDate} — {mess.checkOutDate}</span>
            </div>
          </div>
        );
      case ServiceType.KRP:
        const krp = req as KRPRequest;
        return (
          <div className="space-y-3">
            <div className="grid grid-cols-2 gap-2">
                <div>
                    <p className={detailLabelClass}>Penumpang</p>
                    <p className={detailValueClass}>{krp.passengerName}</p>
                </div>
                <div>
                    <p className={detailLabelClass}>Jumlah</p>
                    <p className={detailValueClass}>{krp.passengerCount} Orang</p>
                </div>
            </div>
            <div className="flex items-center gap-2 pt-2 border-t border-slate-50 dark:border-slate-800/50">
               <Calendar size={12} className="text-slate-400" />
               <span className="text-[10px] font-medium text-slate-500">{krp.departureDate} @ {krp.departureTime}</span>
            </div>
          </div>
        );
      case ServiceType.MAINTENANCE:
        const main = req as MaintenanceRequest;
        return (
          <div className="space-y-3">
            <div>
               <p className={detailLabelClass}>Kategori</p>
               <p className={detailValueClass}>{main.category}</p>
            </div>
            <div className="bg-slate-50 dark:bg-slate-800 p-2.5 rounded-xl border border-slate-100 dark:border-slate-700/50">
               <p className="text-[10px] text-slate-500 dark:text-slate-400 italic leading-relaxed">"{main.detail}"</p>
            </div>
          </div>
        );
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 scrollbar-hide">
      {/* Interactive Status Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <StatusCard 
          status={RequestStatus.REQUESTED} 
          icon={Inbox} 
          colorClass="bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400" 
          activeClass="bg-blue-600" 
        />
        <StatusCard 
          status={RequestStatus.ON_PROGRESS} 
          icon={RefreshCw} 
          colorClass="bg-amber-50 dark:bg-amber-900/20 text-amber-600 dark:text-amber-400" 
          activeClass="bg-amber-500" 
        />
        <StatusCard 
          status={RequestStatus.PENDING} 
          icon={Clock} 
          colorClass="bg-rose-50 dark:bg-rose-900/20 text-rose-600 dark:text-rose-400" 
          activeClass="bg-rose-500" 
        />
        <StatusCard 
          status={RequestStatus.CLOSE} 
          icon={CheckCircle2} 
          colorClass="bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400" 
          activeClass="bg-emerald-500" 
        />
      </div>

      {/* Request Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredRequests.map((req) => (
          <div key={req.id} className="bg-white dark:bg-slate-900 rounded-[1.5rem] border border-slate-200 dark:border-slate-800 p-6 shadow-sm hover:shadow-lg transition-all flex flex-col">
            <div className="flex justify-between items-center mb-5">
              <span className="text-[9px] font-black text-slate-300 dark:text-slate-600 uppercase tracking-widest bg-slate-50 dark:bg-slate-950 px-2 py-1 rounded-md">#{req.id.slice(0, 5)}</span>
              <div className="relative">
                <select 
                    value={req.status}
                    onChange={(e) => onUpdateStatus(req.id, e.target.value as RequestStatus)}
                    className={`text-[10px] font-black rounded-lg pl-3 pr-2 py-1.5 outline-none appearance-none cursor-pointer shadow-sm transition-colors ${
                    req.status === RequestStatus.REQUESTED ? 'bg-blue-50 text-blue-600' :
                    req.status === RequestStatus.ON_PROGRESS ? 'bg-amber-50 text-amber-600' :
                    req.status === RequestStatus.PENDING ? 'bg-rose-50 text-rose-600' :
                    'bg-emerald-50 text-emerald-600'
                    }`}
                >
                    {Object.values(RequestStatus).map(s => (
                    <option key={s} value={s}>{s.toUpperCase()}</option>
                    ))}
                </select>
              </div>
            </div>

            <div className="mb-5 flex-1">
              <h4 className="font-black text-slate-900 dark:text-white text-base leading-tight">
                {req.type === ServiceType.MAINTENANCE ? (req as MaintenanceRequest).requesterName : (req as any).requesterName}
              </h4>
              <p className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider mt-1">{req.function}</p>
            </div>

            <div className="pt-5 border-t border-slate-50 dark:border-slate-800/50">
              {renderRequestDetails(req)}
            </div>
          </div>
        ))}
      </div>

      {filteredRequests.length === 0 && (
        <div className="py-24 text-center bg-white dark:bg-slate-900 rounded-[2rem] border-2 border-dashed border-slate-200 dark:border-slate-800 transition-colors">
          <div className="w-16 h-16 bg-slate-50 dark:bg-slate-800/50 rounded-full flex items-center justify-center text-slate-300 dark:text-slate-600 mx-auto mb-4">
            <Inbox size={32} />
          </div>
          <p className="text-slate-400 dark:text-slate-500 font-bold text-sm uppercase tracking-widest">Tidak ada data</p>
        </div>
      )}
    </div>
  );
};

export default DashboardView;

import React, { useState } from 'react';
import { ServiceType, RequestStatus, MessRequest } from '../types';
