        <div>
          <label className={labelClasses}>Fungsi / Departemen</label>
          <input
            required
            type="text"
            className={inputClasses}
            placeholder="Unit kerja..."
            value={formData.function}
            onChange={e => setFormData(prev => ({ ...prev, function: e.target.value }))}
