import { Save, Repeat } from 'lucide-react';

interface Props {
  onSubmit: (req: KRPRequest) => void;
}

const KRPRequestForm: React.FC<Props> = ({ onSubmit }) => {
  const [formData, setFormData] = useState({
    passengerName: '',
    passengerCount: 1,
    function: '',
    passengerPhone: '',
    departureDate: '',
    departureTime: '',
    isRoundTrip: false,
