  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newRequest: KRPRequest = {
      ...formData,
      id: Math.random().toString(36).substring(2, 9),
      type: ServiceType.KRP,
      status: RequestStatus.REQUESTED,
      createdAt: new Date().toISOString(),
    };
